function App() {
  const url = `https://api.thecatapi.com/v1/images/search?limit=10&breed_ids=beng&api_key=`;
  const api_key = 'live_I3nzKnTpNjzyXLZp0RtbUU1mRjTwK7uAEECexmUv6u3djBsNDYSaX4Isn5PDyZo9'
  const [items,setItems] = useState([]);

  useEffect(()=>{
    fetch(url,{header: {'x-api-key': api_key}})
      .then(res=>res.json())
      .then(data=>setItems(data))
  },[])

  const onChangeInclude =()=>{

  }


  return (
    <>
    <h1>고양이품종검색</h1>
        {items.map((item)=>{
        return(<>

        <input type="text" name="title" placeholder="검색" onChange={onChangeInclude}/>
        <li>{item.id}</li>
        </>)
        })}
    </>

      )
}

export default App;
